import re

def parse_yaml(text):
    res = {}
    lines = text.splitlines()
    i = 0
    while i < len(lines):
        line = lines[i].rstrip()
        if not line or line.strip().startswith('#') or line.strip() == '---':
            i += 1
            continue

        # Simple key-value: "key: value"
        kv_match = re.match(r'^(\w+):\s*(.*)$', line)
        if kv_match:
            key, val = kv_match.groups()
            if not val:
                # Might be a list or a nested object
                if key == 'cheatpaths':
                    paths = []
                    i += 1
                    while i < len(lines):
                        if not lines[i].strip() or lines[i].strip().startswith('#'):
                            i += 1
                            continue
                        if not lines[i].startswith('  -'):
                            break
                        # Start of a new path object
                        path_obj = {}
                        # Parse the first line of the object: "  - name: personal"
                        m = re.match(r'^\s*-\s*(\w+):\s*(.*)$', lines[i])
                        if m:
                            pk, pv = m.groups()
                            path_obj[pk] = pv.strip()
                        i += 1
                        # Parse subsequent lines of the same object
                        while i < len(lines) and lines[i].startswith('    '):
                            m = re.match(r'^\s*(\w+):\s*(.*)$', lines[i])
                            if m:
                                pk, pv = m.groups()
                                if pv.startswith('[') and pv.endswith(']'):
                                    # Tags: [ tag1, tag2 ]
                                    path_obj[pk] = [t.strip() for t in pv[1:-1].split(',') if t.strip()]
                                elif pv.lower() in ('true', 'false'):
                                    path_obj[pk] = pv.lower() == 'true'
                                else:
                                    path_obj[pk] = pv.strip()
                            i += 1
                        paths.append(path_obj)
                    res[key] = paths
                    continue
            else:
                if val.lower() == 'true':
                    res[key] = True
                elif val.lower() == 'false':
                    res[key] = False
                else:
                    res[key] = val
        i += 1
    return res

def parse_frontmatter(text):
    if not text.startswith('---'):
        return {}, text

    parts = re.split(r'^---\s*$', text, maxsplit=2, flags=re.MULTILINE)
    if len(parts) < 3:
        return {}, text

    fm_text = parts[1]
    content = parts[2].lstrip()

    fm = {}
    for line in fm_text.splitlines():
        m = re.match(r'^(\w+):\s*(.*)$', line)
        if m:
            k, v = m.groups()
            if v.startswith('[') and v.endswith(']'):
                fm[k] = [t.strip() for t in v[1:-1].split(',') if t.strip()]
            else:
                fm[k] = v.strip()
    return fm, content
