{"command":"cat <<'EOF' > config_utils.py
def get_config_path():
    if 'CHEAT_CONFIG_PATH' in os.environ:
        return os.path.expanduser(os.environ['CHEAT_CONFIG_PATH'])
    home = os.path.expanduser('~')
    xdg_config = os.environ.get('XDG_CONFIG_HOME', os.path.join(home, '.config'))

    paths = [
        os.path.join(xdg_config, 'cheat', 'conf.yml'),
        os.path.join(home, '.cheat', 'conf.yml'),
        '/etc/cheat/conf.yml'
    ]
    for p in paths:
        if os.path.exists(p):
            return p
    return paths[0]
